 const deletePlaying=(clip:Clip)=>{const next=nextPending(clip.id)??reviewList[playIndex+1]??reviewList[playIndex-1];deleteClipSoon(clip.id,clip.streamer);setDialog(next&&next.id!==clip.id?"play:"+next.id:null);};
 const onDialogKey=(e:React.KeyboardEvent<HTMLDialogElement>)=>{
  if(typingIn(e.target)||e.ctrlKey||e.metaKey||e.altKey)return;
  const k=e.key,onVideo=e.target instanceof HTMLVideoElement;
  if(playClip){
   if(k==="Enter"){e.preventDefault();if(playClip.review!=="approved")decide(playClip,"approved");else step(1);}
   else if(k==="Delete"||k==="Backspace"){e.preventDefault();deletePlaying(playClip);}
   else if(k==="r"||k==="R"){e.preventDefault();if(playClip.review!=="rejected")decide(playClip,"rejected");else step(1);}
   else if((k==="e"||k==="E")&&playClip.editable){e.preventDefault();setDialog(null);setEditing(playClip.id);}
   else if((k==="ArrowRight"||k==="ArrowLeft")&&!onVideo){e.preventDefault();step(k==="ArrowRight"?1:-1);}
   else if(k===" "&&!onVideo&&!(e.target instanceof HTMLButtonElement)){e.preventDefault();const v=modal.current?.querySelector<HTMLVideoElement>("video.clip-player");if(v){if(v.paused)void v.play();else v.pause();}}
   return;
  }
  // Other dialogs: Enter presses the main button (forms already submit on Enter).
  if(k==="Enter"&&!(e.target instanceof HTMLButtonElement)&&!(e.target instanceof HTMLAnchorElement)){const b=modal.current?.querySelector<HTMLButtonElement>("[data-enter]:not(:disabled)");if(b){e.preventDefault();b.click();}}
 };
 // Page keys, outside dialogs and the editor: Delete removes the ticked clips (after asking), Esc unticks them,
 // Ctrl+Z brings back the clip just deleted.
 const pageKey=useRef<(e:KeyboardEvent)=>void>(()=>{});
 useEffect(()=>{pageKey.current=e=>{
  if(e.defaultPrevented||dialog||editing||typingIn(e.target))return;
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="z"&&undo){e.preventDefault();undo.run();return;}
  if(view!=="Clip library"||!selectedIds.length)return;
  if(e.key==="Delete"||e.key==="Backspace"){e.preventDefault();setDialog("deleteMany");}
  else if(e.key==="Escape")setSelected([]);
 };});
 useEffect(()=>{const on=(e:KeyboardEvent)=>pageKey.current(e);window.addEventListener("keydown",on);return()=>window.removeEventListener("keydown",on);},[]);
 const connectHref=(streamer?:string,another=false)=>"/api/connections/instagram/start"+(streamer||another?"?":"")+[streamer&&"streamer="+streamer,another&&"another=1"].filter(Boolean).join("&");
 const openAdd=()=>{setError("");setAddAccounts(accounts.filter(a=>a.status==="connected").map(a=>a.id));setDialog("add");};
 const review=(id:string,decision:Review)=>mutate({action:"reviewClip",id,review:decision},{optimistic:d=>({...d,clips:d.clips.map(c=>c.id===id?{...c,review:decision}:c)})});
 const setStatus=(id:string,status:string)=>mutate({action:"status",id,status},{optimistic:d=>({...d,streamers:d.streamers.map(s=>s.id===id?{...s,status}:s)})});
 const reviewPosts=(ids:string[],op:"queue"|"skip")=>mutate({action:"reviewPosts",ids,op},{optimistic:d=>({...d,posts:d.posts.map(p=>ids.includes(p.id)?{...p,state:op==="queue"?"queued" as const:"skipped" as const}:p)})});
 const recentError=engine?.lastError&&engine.lastErrorAt&&loadedAt-Date.parse(engine.lastErrorAt)<ERROR_RECENT_MS?{message:engine.lastError,at:engine.lastErrorAt}:null;
 // Recording priority, shown once the user has set an order.
 const ranks=streamers.some(s=>s.priority!=null)?new Map(priorityOrder(streamers).map((s,i)=>[s.id,i+1])):null;
 const filtered=streamers.filter(s=>filter==="All platforms"||s.platform===filter);
 const changeView=(next:string)=>{setView(next);setError("");};
 const addButton=<button className="primary" disabled={!data||busy} onClick={openAdd}><Plus size={17}/>Add streamer</button>;
 const streamerTable=<section className="panel streamer-panel"><div className="panel-heading"><div><h2>Your streamers <span className="count">{streamers.length}</span></h2><p>Channels you've added to your workspace</p></div><div className="panel-tools">{streamers.length>1&&<button className="secondary" disabled={busy||!data} title="Choose who is recorded first when several streamers are live" onClick={()=>{setError("");setDialog("priority");}}><ListOrdered size={15}/>Recording priority</button>}<select aria-label="Filter streamers by platform" value={filter} onChange={e=>setFilter(e.target.value)}>{["All platforms",...sourcePlatforms].map(p=><option key={p}>{p}</option>)}</select></div></div>
  {filtered.length?<div className="table-scroll"><table className="phone-cards"><thead><tr><th>Streamer</th><th>Source</th><th>Automation</th><th>Stream status</th><th>Posts to</th><th>Controls</th></tr></thead><tbody>{filtered.map(s=><tr key={s.id}><td className="c-person"><div className="person"><span className="avatar">{s.name.slice(0,2).toUpperCase()}</span><div><strong>{s.name}</strong><a href={s.url} target="_blank" rel="noreferrer">Open channel <ExternalLink size={11}/></a></div></div></td><td className="c-source"><span className="inline-brand"><Brand name={s.platform}/>{s.platform}</span></td><td className="c-auto"><span className={"tag "+(s.status==="armed"?"lime":"")}>{s.status==="armed"?"Enabled":s.status==="paused"?"Paused":"Stopped"}</span>{s.publish_mode&&<small className="muted publish-mode" title="This streamer's own publishing mode (Edit streamer to change it)"> &middot; {s.publish_mode==="review"?"Review first":"Posts directly"}</small>}{ranks&&<small className="mode-note" title="Recording priority (Recording priority button above)">Priority {ranks.get(s.id)}</small>}{s.capture_mode&&s.capture_mode!=="clip"&&<small className="mode-note">{s.capture_mode==="record"?"Records whole stream":"Clips live + records"}</small>}</td><td className="c-status"><LiveStatus s={s} now={loadedAt}/></td><td className="c-posts" data-label="Posts to"><button className="routing" disabled={busy||!data} title="Choose which accounts post this streamer's clips" onClick={()=>{setAssignDraft(s.accounts);setDialog("assign:"+s.id);}}>{s.accounts.length?s.accounts.map(id=><span key={id} className="tag">@{accountName(id)??"account"}</span>):<span className="muted">Library only</span>}<Pencil size={12}/></button></td><td className="c-actions"><div className="row-actions"><button className="icon-button" disabled={busy} aria-label={(s.status==="armed"?"Pause ":"Enable ")+s.name} title={s.status==="armed"?"Pause":"Enable preference"} onClick={()=>void setStatus(s.id,s.status==="armed"?"paused":"armed")}>{s.status==="armed"?<Pause size={16}/>:<Play size={16}/>}</button><button className="icon-button" disabled={busy} aria-label={"Stop "+s.name} title="Stop" onClick={()=>void setStatus(s.id,"stopped")}><Square size={14}/></button><button className="icon-button" aria-label={"Edit "+s.name} title="Edit streamer" disabled={busy} onClick={()=>{setError("");setDialog("editStreamer:"+s.id);}}><Pencil size={15}/></button><button className="icon-button" aria-label={"Remove "+s.name} title="Remove streamer" onClick={()=>setDialog("remove:"+s.id)}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div>:<div className="empty"><div className="empty-icon"><Radio size={28}/></div><h3>{streamers.length?"No streamers on this platform":"Your next great clip starts here"}</h3><p>{streamers.length?"Choose another platform to see your channels.":"Add a Twitch, YouTube, Kick or TikTok channel to begin setting up your clipping workflow."}</p>{!streamers.length&&addButton}<div className="source-strip">{sourcePlatforms.map(p=><span key={p}><Brand name={p}/>{p}</span>)}</div></div>}
  <div className="panel-foot"><span className="small-dot"/>Live status comes from your clip worker and refreshes while automation is running.</div></section>;
 const accountRow=(a:Account)=>{const linked=streamers.filter(s=>s.accounts.includes(a.id));return <div key={a.id} className="account-row"><div className="person"><Brand name={platformName(a.platform)}/><div><strong>@{a.username}</strong><small className={a.status==="connected"?"muted":"engine-error"}>{platformName(a.platform)} · {a.status==="connected"?"Connected "+when(a.connected_at):"Reconnect needed"}{a.last_error?" · "+a.last_error:""}</small></div></div><button type="button" className="account-streamers routing" disabled={busy||!streamers.length} title="Choose which streamers post to this account" onClick={()=>{setAssignDraft(linked.map(s=>s.id));setDialog("streamersFor:"+a.id);}}>{linked.length?linked.map(s=><span key={s.id} className="tag lime">{s.name}</span>):<span className="muted">{streamers.length?"Not posting for any streamer yet":"Add a streamer first"}</span>}<Pencil size={12}/></button><div className="connection-actions">{streamers.length>0&&<button className="secondary" disabled={busy} onClick={()=>{setAssignDraft(linked.map(s=>s.id));setDialog("streamersFor:"+a.id);}}><Plus size={14}/>{linked.length?"Streamers":"Add streamers"}</button>}{a.status!=="connected"&&a.provider!=="zernio"&&<a className="secondary" href={connectHref(undefined,true)} target="_top">Reconnect</a>}{a.provider==="zernio"&&a.status!=="connected"&&<a className="secondary" href={"/api/connections/zernio/start?platform="+a.platform} target="_top">Reconnect</a>}{a.provider==="zernio"&&hasOptions(a.platform)&&<button className="secondary" disabled={busy} onClick={()=>setDialog("options:"+a.id)}>Options</button>}<button className="secondary" disabled={busy} onClick={()=>setDialog("disconnect:"+a.id)}>Disconnect</button></div></div>;};
 // Social accounts: the Zernio key, connect buttons for each platform and the connected accounts (publishing-setup.tsx).
